using System.Text.RegularExpressions;

namespace DotCharter.Tests.Infrastructure;

/// <summary>
///     The repository goes public without data transcribed from Rocksmith's soundbanks
///     (#755): the amp chains and knob curves are built from the player's own install at
///     run time (the plugin's game-table builder, and since JuceSharp #25 the native amp
///     chains too: <c>RsAmpChainRowBuilder</c>). This fails the day a generated game
///     table comes back — the generated file itself, the old generator or its marker in
///     any source, or a curve or chorus table written out as literals in the converter.
/// </summary>
public sealed partial class RsGameDataLintTests
{
    private const string ConversionFolder = "DotCharter.Tone/Audio/Dsp/RsToneConversion";
    private const string GeneratorMarker = "GENERATED by tools/rs-game-chains";

    [Fact]
    public void NoGeneratedGameTable_IsInTheTree()
    {
        var root = TestPaths.RepoRoot();
        var files = SourceFiles(root).ToList();
        // The sentinels the scan must reach: a lint that lists no files passes vacuously.
        // (The builders themselves are in the optional plugin, outside this scan.)
        Assert.Contains(files, f => f.EndsWith("RsGameCurves.cs", StringComparison.Ordinal));
        Assert.Contains(files, f => f.EndsWith("RsMbCompModel.cs", StringComparison.Ordinal));

        var hits = new List<string>();
        foreach (var file in files)
        {
            var relative = Path.GetRelativePath(root, file).Replace('\\', '/');
            hits.AddRange(Violations(relative, File.ReadAllText(file)).Select(v => $"{relative}: {v}"));
        }

        Assert.True(hits.Count == 0,
            "Rocksmith game data is back in the tree; the tables come from the player's install (RsGameTables, #755):\n" +
            string.Join('\n', hits));
    }

    /// <summary>The probe twin: what the removed tables looked like is caught, the
    /// code that replaced them is not.</summary>
    [Fact]
    public void TheRules_CatchTheRemovedShapes_AndPassTheirReplacement()
    {
        Assert.NotEmpty(Violations(ConversionFolder + "/RsAmpChains.g.cs", "namespace X;"));
        Assert.NotEmpty(Violations("DotCharter.Tone/Other.cs", "// Foo.g.cs: " + GeneratorMarker + "/gen.py"));
        Assert.NotEmpty(Violations(ConversionFolder + "/RsGameCurves.cs",
            "public static readonly WwiseCurve Q = WwiseCurve.Plain(0f, 0.8f, 1f, 2.5f, WwiseCurveShape.Linear);"));
        Assert.NotEmpty(Violations(ConversionFolder + "/X.cs", "var c = new WwiseCurve(-1f, 2f, 3f, 4f, s, k);"));
        Assert.NotEmpty(Violations(ConversionFolder + "/X.cs", "new RsFlangerChorus(\"Pedal_Chorus\", 12f, 1, 0f, -1f,"));
        Assert.NotEmpty(Violations(ConversionFolder + "/X.cs", "        new(\"Amp_AT120\", \"AT-120\", \"amp_at120.bnk\", 4, 1,"));
        Assert.NotEmpty(Violations("tools/rs-game-chains/gen_rsamp_chains.py", "import struct"));
        Assert.NotEmpty(Violations("tools/x.py", "CPP_OUT = os.path.join(ROOT, 'JuceSharp', 'dcdsp_rsamp_chains.h')"));

        Assert.Empty(Violations(ConversionFolder + "/GameTableBuilder.cs",
            "return new WwiseCurve(p0.X, p0.Y * scale, p1.X, p1.Y * scale, shape, scaling);"));
        Assert.Empty(Violations(ConversionFolder + "/X.cs", "new RsFlangerChorus(key, first.F32(0), flangers.Count,"));
        Assert.Empty(Violations("DotCharter.Tests/Audio/X.cs", "WwiseCurve.Plain(1f, 10f, 100f, 1000f, shape)"));

        // #167: the MB Comp model is the install's, fitted at run time.
        const string mbSection = "// ---------------------------------------------------- Bass_Pedal_MBComp\n";
        Assert.NotEmpty(Violations(ConversionFolder + "/X.cs", "static readonly RsMbCompModel M = new RsMbCompModel([], [], 1.5f,"));
        Assert.NotEmpty(Violations(ConversionFolder + "/X.cs", "new RsMbCompModel(\n    [WwiseCurve.Plain(a, b, c, d, s)], o, -3f,"));
        Assert.NotEmpty(Violations(ConversionFolder + "/RsToneConverter.GameCurveGear.cs",
            mbSection + "p.Set(\"thresholdDb\", -21.5f - 0.3f * compress);"));
        Assert.NotEmpty(Violations(ConversionFolder + "/RsMbCompModel.cs", "Set(\"ratio\", 3.2f, \"the ratio\");"));
        Assert.NotEmpty(Violations(ConversionFolder + "/RsMbCompModel.cs", "p[\"kneeDb\"] = 6f;"));
        Assert.Empty(Violations(ConversionFolder + "/RsMbCompModel.cs", "Set(\"ratio\", ratio, \"the ratio\");"));
        Assert.Empty(Violations(ConversionFolder + "/X.cs", "return new RsMbCompModel(input, output, (float)fixedDb, (float)t, (float)r,"));
        Assert.Empty(Violations(ConversionFolder + "/X.cs", "new RsMbCompModel(CurvesOf(c), CurvesOf(d), f[0], f[1], f[2],"));
        Assert.Empty(Violations(ConversionFolder + "/RsToneConverter.GameCurveGear.cs",
            mbSection + "p.Set(\"thresholdDb\", model.ThresholdAt(compress));\n// ---------- Pedal_LoFiFilter\np.Set(\"ratio\", 4f);"));
    }

    private static IEnumerable<string> Violations(string relative, string text)
    {
        if (Path.GetFileName(relative).EndsWith(".g.cs", StringComparison.Ordinal) && relative.StartsWith(ConversionFolder, StringComparison.Ordinal))
            yield return "a generated file in the conversion folder";
        // The app builds every table itself now (JuceSharp #25): the generator that wrote
        // the native header is gone, and so is the header.
        if (Path.GetFileName(relative) == "gen_rsamp_chains.py") yield return "the game-table generator";
        var exempt = relative.StartsWith("DotCharter.Tests/", StringComparison.Ordinal);
        if (!exempt && text.Contains(GeneratorMarker, StringComparison.Ordinal))
            yield return "the game-table generator's marker";
        if (!exempt && text.Contains("dcdsp_rsamp_chains.h", StringComparison.Ordinal) && Path.GetExtension(relative) is ".py" or ".cs")
            yield return "code that writes or reads the removed native chain header";
        if (!relative.StartsWith(ConversionFolder + "/", StringComparison.Ordinal)) yield break;
        if (LiteralCurve().IsMatch(text)) yield return "a WwiseCurve written out as literals";
        if (LiteralChorus().IsMatch(text)) yield return "a chorus bank written out as literals";
        if (LiteralAmpRow().IsMatch(text)) yield return "an amp row written out as literals";
        if (LiteralMbComp().IsMatch(text)) yield return "an MB Comp model written out as literals (#167)";
        var mbCompText = Path.GetFileName(relative) switch
        {
            "RsToneConverter.GameCurveGear.cs" => MbCompSection(text),
            "RsMbCompModel.cs" => text,
            _ => ""
        };
        if (LiteralMbCompParam().IsMatch(mbCompText))
            yield return "an MB Comp compressor parameter set from a number, not from the install's model (#167)";
    }

    /// <summary>The MB Comp's section of the converter, from its banner to the next one,
    /// so the other gears' own constants stay out of scope.</summary>
    private static string MbCompSection(string text)
    {
        var start = text.IndexOf("// ---------------------------------------------------- Bass_Pedal_MBComp", StringComparison.Ordinal);
        if (start < 0) return "";
        var end = text.IndexOf("// -------", start + 10, StringComparison.Ordinal);
        return end < 0 ? text[start..] : text[start..end];
    }

    private static IEnumerable<string> SourceFiles(string root)
    {
        string[] skipped = ["bin", "obj", ".git", ".claude", ".codex", ".vs", "JuceSharp", "TestData", "TestResults", "node_modules", "artifacts", "addons"];
        var stack = new Stack<string>([root]);
        while (stack.Count > 0)
        {
            var dir = stack.Pop();
            foreach (var sub in Directory.EnumerateDirectories(dir))
            {
                if (!skipped.Contains(Path.GetFileName(sub), StringComparer.OrdinalIgnoreCase)) stack.Push(sub);
            }

            foreach (var file in Directory.EnumerateFiles(dir))
            {
                var ext = Path.GetExtension(file);
                if (ext is ".cs" or ".py" or ".json" or ".h" or ".md") yield return file;
            }
        }
    }

    [GeneratedRegex(@"(?:WwiseCurve\.(?:Plain|LogHz|Db)|new\s+WwiseCurve)\(\s*-?\d")]
    private static partial Regex LiteralCurve();

    [GeneratedRegex("new\\s+RsFlangerChorus\\(\\s*\"")]
    private static partial Regex LiteralChorus();

    [GeneratedRegex("new\\(\\s*\"(?:Amp|Bass_Amp|DI_Amp)_[A-Za-z0-9]+\",\\s*\"")]
    private static partial Regex LiteralAmpRow();

    /// <summary>An <c>RsMbCompModel</c> given a numeric literal as an argument or array element.</summary>
    [GeneratedRegex(@"new\s+RsMbCompModel\([^;]*?[(,]\s*\[?\s*[-+]?\d")]
    private static partial Regex LiteralMbComp();

    /// <summary>A compressor parameter the MB Comp sets from a numeric literal.</summary>
    [GeneratedRegex(@"(?:\bSet\(|\[)""(?:thresholdDb|ratio|kneeDb|makeupDb|attackMs|releaseMs)""(?:,|\]\s*=)\s*[-+(]?\s*\d")]
    private static partial Regex LiteralMbCompParam();
}
